demo1_in = extract_array(demos[0]['input'])
demo1_out = extract_array(demos[0]['output'])

# Find connected components of 2s
def find_components(grid):
    """Find connected components using 4-connectivity."""
    H, W = grid.shape
    visited = set()
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r, c] == 2 and (r, c) not in visited:
                # BFS to find component
                component = []
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr, nc] == 2 and (nr, nc) not in visited:
                            queue.append((nr, nc))
                components.append(sorted(component))
    return components

